    /* [MS-XLSB] 2.1.7.61 Workbook */
    function write_wb_bin(wb, opts) {
    	var ba = buf_array();
    	write_record(ba, "BrtBeginBook");
    	write_record(ba, "BrtFileVersion", write_BrtFileVersion());
    	/* [[BrtFileSharingIso] BrtFileSharing] */
    	write_record(ba, "BrtWbProp", write_BrtWbProp(wb.Workbook && wb.Workbook.WBProps || null));
    	/* [ACABSPATH] */
    	/* [[BrtBookProtectionIso] BrtBookProtection] */
    	write_BOOKVIEWS(ba, wb);
    	write_BUNDLESHS(ba, wb);
    	/* [FNGROUP] */
    	/* [EXTERNALS] */
    	/* *BrtName */
    	/* write_record(ba, "BrtCalcProp", write_BrtCalcProp()); */
    	/* [BrtOleSize] */
    	/* *(BrtUserBookView *FRT) */
    	/* [PIVOTCACHEIDS] */
    	/* [BrtWbFactoid] */
    	/* [SMARTTAGTYPES] */
    	/* [BrtWebOpt] */
    	/* write_record(ba, "BrtFileRecover", write_BrtFileRecover()); */
    	/* [WEBPUBITEMS] */
    	/* [CRERRS] */
    	/* FRTWORKBOOK */
    	write_record(ba, "BrtEndBook");

    	return ba.end();
    }
    function parse_wb(data, name, opts) {
    	if(name.slice(-4)===".bin") return parse_wb_bin((data), opts);
    	return parse_wb_xml((data), opts);
    }

    function parse_ws(data, name, idx, opts, rels, wb, themes, styles) {
    	if(name.slice(-4)===".bin") return parse_ws_bin((data), opts, idx, rels, wb, themes, styles);
    	return parse_ws_xml((data), opts, idx, rels, wb, themes, styles);
    }

    function parse_cs(data, name, idx, opts, rels, wb, themes, styles) {
    	if(name.slice(-4)===".bin") return parse_cs_bin((data), opts, idx, rels, wb);
    	return parse_cs_xml((data), opts, idx, rels, wb);
    }

    function parse_ms(data, name, idx, opts, rels, wb, themes, styles) {
    	if(name.slice(-4)===".bin") return parse_ms_bin();
    	return parse_ms_xml();
    }

    function parse_ds(data, name, idx, opts, rels, wb, themes, styles) {
    	if(name.slice(-4)===".bin") return parse_ds_bin();
    	return parse_ds_xml();
    }

    function parse_sty(data, name, themes, opts) {
    	if(name.slice(-4)===".bin") return parse_sty_bin((data), themes, opts);
    	return parse_sty_xml((data), themes, opts);
    }

    function parse_theme(data, name, opts) {
    	return parse_theme_xml(data, opts);
    }

    function parse_sst(data, name, opts) {
    	if(name.slice(-4)===".bin") return parse_sst_bin((data), opts);
    	return parse_sst_xml((data), opts);
    }

    function parse_cmnt(data, name, opts) {
    	if(name.slice(-4)===".bin") return parse_comments_bin((data), opts);
    	return parse_comments_xml((data), opts);
    }

    function parse_cc(data, name, opts) {
    	if(name.slice(-4)===".bin") return parse_cc_bin((data));
    	return parse_cc_xml((data));
    }

    function parse_xlink(data, rel, name, opts) {
    	if(name.slice(-4)===".bin") return parse_xlink_bin((data), rel, name, opts);
    	return parse_xlink_xml();
    }

    function write_wb(wb, name, opts) {
    	return (name.slice(-4)===".bin" ? write_wb_bin : write_wb_xml)(wb);
    }

    function write_ws(data, name, opts, wb, rels) {
    	return (name.slice(-4)===".bin" ? write_ws_bin : write_ws_xml)(data, opts, wb, rels);
    }

    function write_sty(data, name, opts) {
    	return (name.slice(-4)===".bin" ? write_sty_bin : write_sty_xml)(data, opts);
    }

    function write_sst(data, name, opts) {
    	return (name.slice(-4)===".bin" ? write_sst_bin : write_sst_xml)(data, opts);
    }

    function write_cmnt(data, name, opts) {
    	return (name.slice(-4)===".bin" ? write_comments_bin : write_comments_xml)(data);
    }
    /*
    function write_cc(data, name:string, opts) {
    	return (name.slice(-4)===".bin" ? write_cc_bin : write_cc_xml)(data, opts);
    }
    */
    var attregexg2=/([\w:]+)=((?:")([^"]*)(?:")|(?:')([^']*)(?:'))/g;
    var attregex2=/([\w:]+)=((?:")(?:[^"]*)(?:")|(?:')(?:[^']*)(?:'))/;
    function xlml_parsexmltag(tag, skip_root) {
    	var words = tag.split(/\s+/);
    	var z = ([]); if(!skip_root) z[0] = words[0];
    	if(words.length === 1) return z;
    	var m = tag.match(attregexg2), y, j, w, i;
    	if(m) for(i = 0; i != m.length; ++i) {
    		y = m[i].match(attregex2);
    if((j=y[1].indexOf(":")) === -1) z[y[1]] = y[2].slice(1,y[2].length-1);
    		else {
    			if(y[1].slice(0,6) === "xmlns:") w = "xmlns"+y[1].slice(6);
    			else w = y[1].slice(j+1);
    			z[w] = y[2].slice(1,y[2].length-1);
    		}
    	}
    	return z;
    }
    function xlml_parsexmltagobj(tag) {
    	var words = tag.split(/\s+/);
    	var z = {};
    	if(words.length === 1) return z;
    	var m = tag.match(attregexg2), y, j, w, i;
    	if(m) for(i = 0; i != m.length; ++i) {
    		y = m[i].match(attregex2);
    if((j=y[1].indexOf(":")) === -1) z[y[1]] = y[2].slice(1,y[2].length-1);
    		else {
    			if(y[1].slice(0,6) === "xmlns:") w = "xmlns"+y[1].slice(6);
    			else w = y[1].slice(j+1);
    			z[w] = y[2].slice(1,y[2].length-1);
    		}
    	}
    	return z;
    }

    // ----

    function xlml_format(format, value) {
    	var fmt = XLMLFormatMap[format] || unescapexml(format);
    	if(fmt === "General") return SSF._general(value);
    	return SSF.format(fmt, value);
    }

    function xlml_set_custprop(Custprops, key, cp, val) {
    	var oval = val;
    	switch((cp[0].match(/dt:dt="([\w.]+)"/)||["",""])[1]) {
    		case "boolean": oval = parsexmlbool(val); break;
    		case "i2": case "int": oval = parseInt(val, 10); break;
    		case "r4": case "float": oval = parseFloat(val); break;
    		case "date": case "dateTime.tz": oval = parseDate(val); break;
    		case "i8": case "string": case "fixed": case "uuid": case "bin.base64": break;
    		default: throw new Error("bad custprop:" + cp[0]);
    	}
    	Custprops[unescapexml(key)] = oval;
    }

    function safe_format_xlml(cell, nf, o) {
    	if(cell.t === 'z') return;
    	if(!o || o.cellText !== false) try {
    		if(cell.t === 'e') { cell.w = cell.w || BErr[cell.v]; }
    		else if(nf === "General") {
    			if(cell.t === 'n') {
    				if((cell.v|0) === cell.v) cell.w = SSF._general_int(cell.v);
    				else cell.w = SSF._general_num(cell.v);
    			}
    			else cell.w = SSF._general(cell.v);
    		}
    		else cell.w = xlml_format(nf||"General", cell.v);
    	} catch(e) { if(o.WTF) throw e; }
    	try {
    		var z = XLMLFormatMap[nf]||nf||"General";
    		if(o.cellNF) cell.z = z;
    		if(o.cellDates && cell.t == 'n' && SSF.is_date(z)) {
    			var _d = SSF.parse_date_code(cell.v); if(_d) { cell.t = 'd'; cell.v = new Date(_d.y, _d.m-1,_d.d,_d.H,_d.M,_d.S,_d.u); }
    		}
    	} catch(e) { if(o.WTF) throw e; }
    }

    function process_style_xlml(styles, stag, opts) {
    	if(opts.cellStyles) {
    		if(stag.Interior) {
    			var I = stag.Interior;
    			if(I.Pattern) I.patternType = XLMLPatternTypeMap[I.Pattern] || I.Pattern;
    		}
    	}
    	styles[stag.ID] = stag;
    }

    /* TODO: there must exist some form of OSP-blessed spec */
